document.addEventListener("DOMContentLoaded",function(){const e=document.getElementById("age-form"),t=document.getElementById("age-result");e.addEventListener("submit",function(e){e.preventDefault();const n=document.getElementById("birthdate").value,a=new Date(n),o=new Date;if(!n||a>o)return t.textContent="Please enter a valid birth date (in the past).",void 0;let d=o.getFullYear()-a.getFullYear(),r=o.getMonth()-a.getMonth(),g=o.getDate()-a.getDate();if(g<0){r--;g+=new Date(o.getFullYear(),o.getMonth(),0).getDate()}r<0&&(d--,r+=12);const l=1===d?"year":"years",u=1===r?"month":"months",i=1===g?"day":"days";t.innerHTML=`\n      <b>Your age:</b><br>\n      ${d} ${l}, ${r} ${u}, ${g} ${i}\n    `})});